mapper.select:
select from cynexus_appl_market.portfolio_review_anchor where principal_key=#{principalKey} and tenant_key=#{tenantKey} and deleted_at is null and symbol=#{symbol}
and occurred_at at time zone 'Asia/Shanghai' >= #{tradeDate}::timestamp and occurred_at at time zone 'Asia/Shanghai' < #{tradeDate}::timestamp + interval '1 day'
order by occurred_at asc, id asc
